# Load credentials from secure ~/.credentials/ folder
# Uses "User" scope so IDEs (Antigravity) and terminals pick up env vars without admin
$credsPath = "$env:USERPROFILE\.credentials"

if (Test-Path "$credsPath\github.key") {
    $val = (Get-Content "$credsPath\github.key" -Raw).Trim()
    [System.Environment]::SetEnvironmentVariable("GITHUB_PERSONAL_ACCESS_TOKEN", $val, "User")
    [System.Environment]::SetEnvironmentVariable("GITHUB_PERSONAL_ACCESS_TOKEN", $val, "Process")
}

if (Test-Path "$credsPath\tavily.key") {
    $val = (Get-Content "$credsPath\tavily.key" -Raw).Trim()
    [System.Environment]::SetEnvironmentVariable("TAVILY_API_KEY", $val, "User")
    [System.Environment]::SetEnvironmentVariable("TAVILY_API_KEY", $val, "Process")
}

if (Test-Path "$credsPath\notion.key") {
    $val = (Get-Content "$credsPath\notion.key" -Raw).Trim()
    [System.Environment]::SetEnvironmentVariable("NOTION_TOKEN", $val, "User")
    [System.Environment]::SetEnvironmentVariable("NOTION_TOKEN", $val, "Process")
}

if (Test-Path "$credsPath\google-service-account.json") {
    $val = "$credsPath\google-service-account.json"
    [System.Environment]::SetEnvironmentVariable("GOOGLE_APPLICATION_CREDENTIALS", $val, "User")
    [System.Environment]::SetEnvironmentVariable("GOOGLE_APPLICATION_CREDENTIALS", $val, "Process")
}

# Shared AI Memory for Gemini CLI and Antigravity
$sharedMemory = "$env:USERPROFILE\.shared-ai-memory"
if (Test-Path $sharedMemory) {
    [System.Environment]::SetEnvironmentVariable("GEMINI_CLI_HOME", $sharedMemory, "User")
    [System.Environment]::SetEnvironmentVariable("GEMINI_CLI_HOME", $sharedMemory, "Process")
}

