. C:\Projetos\Stout\load-credentials.ps1;
if ($env:GITHUB_PERSONAL_ACCESS_TOKEN) {
    $remoteUrl = git remote get-url origin;
    if ($remoteUrl -match "github.com") {
        $authenticatedUrl = $remoteUrl -replace "https://", "https://$($env:GITHUB_PERSONAL_ACCESS_TOKEN)@";
        git push $authenticatedUrl master;
    } else {
        Write-Error "Remote URL does not match github.com";
    }
} else {
    Write-Error "GITHUB_PERSONAL_ACCESS_TOKEN not found after loading credentials.";
}

$token = (Get-Content "$env:USERPROFILE\.credentials\github.key" -Raw).Trim();
$remoteUrl = git remote get-url origin;
$authenticatedUrl = $remoteUrl -replace "https://", "https://$($token)@";
git push $authenticatedUrl master;
